class Diagnostic(v24r3.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._snapshot = SnapshotPage(driver, download_checker)
        self._bts_rd_debug_parameters_management = BtsRdDebugParametersManagementPage(driver)
        self._bts_non_default_rd_debug_parameters_management = BtsNonDefaultRdDebugParametersManagementPage(driver)
        self._change_bts_rnd_parameters = ChangeBtsRndParameterPage(driver)
        self._diagnostic_check = DiagnosticCheckPage(driver)
        self._test_models_nr_performance = TestModelsNRPerformancePage(driver)

    @property
    def bts_rd_debug_parameters_management(self):
        return self._bts_rd_debug_parameters_management

    @property
    def bts_non_default_rd_debug_parameters_management(self):
        return self._bts_non_default_rd_debug_parameters_management

    @property
    def change_bts_rnd_parameters(self):
        return self._change_bts_rnd_parameters

    @property
    def test_models_nr_performance(self):
        return self._test_models_nr_performance


class DebugTracingPage(v24r1.diagnostic.DebugTracingPage):

    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)


class DebugTracingPageViewPanel(v24r1.diagnostic.DebugTracingPageViewPanel):

    def configure_iq_capture(
            self,
            enable_capture_on_event,
            capture_event=False,
            ul_subcell_index_list=None,
            dl_subcell_index_list=None,
            lte_ul_cell_ids=None,
            lte_dl_cell_ids=None,
            buffer_cycle=None,
            capture_frame_offset=None,
            radio_configurations=None
    ):
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem, "start", "nearest")
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)

        self._configure_with_capture_on_event(capture_event,
                                              ul_subcell_index_list,
                                              dl_subcell_index_list,
                                              buffer_cycle,
                                              capture_frame_offset,
                                              radio_configurations)

        self._input_cell_ids(self._LTE_UL_CELL_IDS, lte_ul_cell_ids)
        self._input_cell_ids(self._LTE_DL_CELL_IDS, lte_dl_cell_ids)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))
        self.wait_for_visibility_by_xpath(self._CONFIGURING_STATUS)
        self.wait_for_invisibility((By.XPATH, self._CONFIGURING_STATUS))
        return self.get_attribute_by_xpath(self._CONFIGURE_IQ_CAPTURE_STATUS, "title")

    def _configure_with_capture_on_event(self,
                                         capture_event,
                                         ul_subcell_index_list,
                                         dl_subcell_index_list,
                                         buffer_cycle,
                                         capture_frame_offset,
                                         radio_configurations):
        if not capture_event:
            self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)
            self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)
            return

        on_event_xpath = self._CAPTURE_ON_EVENT_FROM_BBU_RU_CHECKBOX.format("Capture on event")
        elem = self.driver.find_element_by_xpath(on_event_xpath)
        self._scroll_elem_into_view(elem)
        self.select_checkbox_by_specified_status(capture_event,
                                                 self._CAPTURE_ON_EVENT_FROM_BBU_RU_INPUT.format("Capture on event"),
                                                 on_event_xpath)
        self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)

        if not buffer_cycle:
            raise ParamValueError('buffer_cycle can not be None with capture_event True')
        if not capture_frame_offset:
            raise ParamValueError('capture_frame_offset can not be None with capture_event True')
        if not radio_configurations:
            raise ParamValueError('radio_configurations can not be None with capture_event True')
        self._select_buffer_cycle(buffer_cycle)
        self._input_capture_frame_offset(capture_frame_offset)
        self._configure_multiple_radios(radio_configurations)

    def _configure_radio(self, rmod, configurations):
        elem = self.driver.find_element_by_xpath(self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list'))
        self._scroll_elem_into_view(elem)
        self.select_element_from_dropdown_list_by_text_and_click(
            configurations['Antenna list'],
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//button"),
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//ul//span")
        )
        self._configure_polarization(rmod,
                                     self._PLUS_FORTY_FIVE_POLARIZATION,
                                     configurations.get(self._PLUS_FORTY_FIVE_POLARIZATION, None))
        self._configure_polarization(rmod,
                                     self._MINUS_FORTY_FIVE_POLARIZATION,
                                     configurations.get(self._MINUS_FORTY_FIVE_POLARIZATION, None))

        self.insert_text_to_enable_element(
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, "Capture activity timer") + "//input"),
            configurations['capture_activity_timer']
        )


