class BtsRdDebugParametersManagementViewPanel(ViewPanel):
    _RAD_DEBUG_DOMAIN = '//*[@class="rad-debug-domains"]//li[span[text()="{}"]]'
    _PARAMETER = '//*[@class="bts-rd-debug-parameter-table"]//th[text()="Parameter name"]'
    _RELOAD_PARAMETERS = '//*[@class="rad-debug-parameters"]//span[text()="Reload Parameters"]'
    _PARAMETER_TR = ('//tr[td//span[translate(text(), "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")='
                     '"{}"]]')
    _CURRENT_VALUE_DROPDOWN_SPAN = _PARAMETER_TR + '//td[@class="current-value-col"]//span[@id]'
    _CURRENT_VALUE_INPUT = _PARAMETER_TR + '//td[@class="current-value-col"]//input'
    _CURRENT_VALUE_OPTIONS = '//ul[contains(@id, "{}")]//span'
    _PERSISTENCY_DROPDOWN_BUTTON = '//*[@class="apply-changes"]//p-dropdown'
    _PERSISTENCY_VALUE_OPTIONS = '//p-dropdownitem//li'
    _APPLY_CHANGES = '//button[span[text()="Apply Changes"]]'
    _APPLY_CHANGES_ONGOING = '//ot-instruction//*[contains(text(), "Apply changes ongoing")]'
    _APPLY_CHANGES_SUCCESS = '//ot-instruction//*[contains(text(), "Apply changes success")]'
    _STATUS = '//ot-instruction'

    def __init__(self, driver):
        super(BtsRdDebugParametersManagementViewPanel, self).__init__(driver)

    def change_rd_debug_parameters(self, domain, parameter_name, current_value=None, persistency=None, timeout=60):
        self.click_enabled_element((By.XPATH, self._RAD_DEBUG_DOMAIN.format(domain)), timeout)
        self.wait_for_enable((By.XPATH, self._PARAMETER), timeout)

        if current_value is not None:
            try:
                current_value_dropdown_button = self._CURRENT_VALUE_DROPDOWN_SPAN.format(parameter_name.lower())
                self.wait_for_enable((By.XPATH, current_value_dropdown_button), 5)
                id_value = self.get_attribute((By.XPATH, current_value_dropdown_button), "id").rsplit('_', 1)[
                    0]
                self.select_element_from_dropdown_list_by_text_and_click(
                    current_value,
                    (By.XPATH, current_value_dropdown_button),
                    (By.XPATH, self._CURRENT_VALUE_OPTIONS.format(id_value)),
                    timeout
                )
            except TimeoutException:
                self.insert_text_to_enable_element((By.XPATH, self._CURRENT_VALUE_INPUT.format(parameter_name.lower())),
                                                   current_value)

        if persistency:
            self.select_element_from_dropdown_list_by_text_and_click(
                persistency,
                (By.XPATH, self._PERSISTENCY_DROPDOWN_BUTTON),
                (By.XPATH, self._PERSISTENCY_VALUE_OPTIONS),
                timeout
            )

    def apply_rd_debug_parameters_changes(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._APPLY_CHANGES), timeout)
        modal = RdDebugParametersApplyChangesModal(self.driver)
        if modal.wait_until_apply_changes_modal_appear():
            modal.apply()
            self.wait_for_visibility_by_xpath(self._APPLY_CHANGES_ONGOING)
            try:
                self.wait_for_invisibility((By.XPATH, self._APPLY_CHANGES_ONGOING))
                self.wait_for_visibility_by_xpath(self._APPLY_CHANGES_SUCCESS, timeout)
                self.wait_for_invisibility((By.XPATH, self._APPLY_CHANGES_SUCCESS))
            except TimeoutException:
                pass
            return self.get_text_by_xpath(self._STATUS)


