class DiagnosticCheckPage(v24r3.diagnostic.DiagnosticCheckPage):

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)


class DiagnosticCheckPageViewPanel(v24r3.diagnostic.DiagnosticCheckPageViewPanel):

    def start_diagnostic_check(self, scope, timeout=60, **kwargs):
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)
        self.select_element_from_dropdown_list_by_text_and_click(scope,
                                                                 (By.XPATH, self._SCOPE_BUTTON),
                                                                 (By.XPATH, self._SCOPE_OPTION),
                                                                 timeout)
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)

        all_service_impact = None
        if self.FULL_DIAGNOSTIC_CHECK == scope:
            all_service_impact = kwargs.get('allow_service_impact', False)
            self.select_checkbox_by_specified_status(all_service_impact,
                                                     self._ALLOW_SERVICE_IMPACT + '//input',
                                                     self._ALLOW_SERVICE_IMPACT)

        elif self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope:
            bts_checkpoints = kwargs.get('bts_checkpoints', [])
            self._select_bts_checkpoints(bts_checkpoints, timeout)

            radio_checkpoints = kwargs.get('radio_checkpoints', [])
            self.rst = False
            self._select_radio_checkpoints(radio_checkpoints, timeout)

        self.click_enabled_element((By.XPATH, self._START_BUTTON), timeout)

        if self.FULL_DIAGNOSTIC_CHECK == scope and all_service_impact:
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(timeout)
            check_modal.start()
            self.wait_for_visibility(self._STARTING_STATUS, timeout)
            return

        if self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope and (not radio_checkpoints or self.rst):
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(5)
            check_modal.start()

        self.wait_for_visibility(self._STARTING_STATUS, timeout)
        self.wait_for_invisibility(self._STARTING_STATUS, timeout)
        self.wait_for_visibility(self._START_SUCCEEDED_STATUS, timeout)
        return self.get_text_by_xpath(self._START_SUCCEEDED_STATUS)


class TestModelsNRPerformancePage(NavigatablePage):

    _MENU_ROUTE_LIST = ["Diagnostic", "Test Models", "NR Performance"]

    def __init__(self, driver):
        super(TestModelsNRPerformancePage, self).__init__(driver)
        self._view_panel = TestModelsNRPerformancePageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_prach_test(self, *args, **kwargs):
        """
        Starts 5G Performance PRACH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: int
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot int
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param preamble_index: Preamble index parameter user wants to run test with.
        :type preamble_index: int
        :param accepted_timing_error: Accepted timing error parameter to run test with.
        :type accepted_timing_error: int
        :param constant_offset: Constant offset parameter to run test with.
        :type constant_offset: int
        :param delay_pattern_duration: Delay pattern Duration parameter to run test with.
        :type delay_pattern_duration: int
        :param prach_format: PRACH format parameter with which test will be started.
        :type prach_format: str
        :param activate_prach_format_c2: activate prach format c2 or not.
        :type activate_prach_format_c2: bool
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        self._view_panel.start_prach_test(*args, **kwargs)


