    def start_pucch_test(self, local_cell, rep_time_int, reception_slot, expectation_slot, f0_sys_num,
                         f2_test_type, beam_id, ru_mode, physical_cell_id, pucch_format, timeout):
        """
        Starts 5G Performance PUCCH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: str
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot str
        :param f0_sys_num: Format0 system number parameter with which test will be started. Works fine ONLY, if
        format parameter is set to 'F0', otherwise it may fail to set up pucch performance test, as there will be no
        parameter in WebUI.
        :type f0_sys_num: str
        :param f2_test_type: Format2 test type parameter with which test will be started. Works fine ONLY, if
        format parameter is set to 'F2', otherwise it may fail to set up pucch performance test, as there will be no
        parameter in WebUI.
        :type f2_test_type: str
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param pucch_format: PUCCH format parameter user wants to run test with.
        Should be provided as exact string value, e.g. 'F0'.
        :type pucch_format: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        _PUCCH_FORMAT_LIST_BUTTON_XPATH = '//div[contains(text(), "PUCCH format:")]/parent::*//button'
        _PUCCH_FORMAT_LIST_OPTIONS_XPATH = '//div[contains(text(), "PUCCH format:")]/parent::*//ul//li'
        _RECEPTION_SLOT_INPUT_XPATH = '//div[contains(text(), "Reception slot:")]/parent::*//input'
        _EXPECTATION_SLOT_INPUT_XPATH = '//div[contains(text(), "Expectation slot:")]/parent::*//input'
        _FORMAT2_TEST_TYPE_LIST_BUTTON_XPATH = '//div[contains(text(), "Format2 test type:")]/parent::*//button'
        _FORMAT2_TEST_TYPE_LIST_OPTIONS_XPATH = '//div[contains(text(), "Format2 test type:")]/parent::*//ul//li'
        _FORMAT0_SYSTEM_NUM_LIST_BUTTON_XPATH = '//div[contains(text(), "Format0 system number:")]/parent::*//button'
        _FORMAT0_SYSTEM_NUM_LIST_OPTIONS_XPATH = '//div[contains(text(), "Format0 system number:")]/parent::*//ul//li'

        self._setup_common_params(local_cell=local_cell,
                                  beam_id=beam_id,
                                  ru_mode=ru_mode,
                                  rep_time_int=rep_time_int,
                                  physical_cell_id=physical_cell_id,
                                  timeout=timeout,
                                  test_type='PUCCH')

        self.insert_text_to_enable_element((By.XPATH, _RECEPTION_SLOT_INPUT_XPATH), str(reception_slot),
                                           timeout)

        self.insert_text_to_enable_element((By.XPATH, _EXPECTATION_SLOT_INPUT_XPATH), str(expectation_slot),
                                           timeout)

        if pucch_format is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                pucch_format,
                (By.XPATH, _PUCCH_FORMAT_LIST_BUTTON_XPATH),
                (By.XPATH, _PUCCH_FORMAT_LIST_OPTIONS_XPATH),
                timeout
            )

        if f0_sys_num is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                f0_sys_num,
                (By.XPATH, _FORMAT0_SYSTEM_NUM_LIST_BUTTON_XPATH),
                (By.XPATH, _FORMAT0_SYSTEM_NUM_LIST_OPTIONS_XPATH),
                timeout
            )

        if f2_test_type is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                f2_test_type,
                (By.XPATH, _FORMAT2_TEST_TYPE_LIST_BUTTON_XPATH),
                (By.XPATH, _FORMAT2_TEST_TYPE_LIST_OPTIONS_XPATH),
                timeout
            )

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def start_prach_test(self, local_cell, rep_time_int, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None, preamble_index=None,
                         accepted_timing_error=None, constant_offset=None, delay_pattern_duration=None,
                         nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, pfa_target=None,
                         prach_config_index=None, root_seq_index=None, zero_zone_config=None, prach_seq_type=None,
                         prach_format=None, activate_prach_format_c2="",
                         timeout=10):
        """
        Starts 5G Performance PRACH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: int
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot int
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param preamble_index: Preamble index parameter user wants to run test with.
        :type preamble_index: int
        :param accepted_timing_error: Accepted timing error parameter to run test with.
        :type accepted_timing_error: int
        :param constant_offset: Constant offset parameter to run test with.
        :type constant_offset: int
        :param delay_pattern_duration: Delay pattern Duration parameter to run test with.
        :type delay_pattern_duration: int
        :param prach_format: PRACH format parameter with which test will be started.
        :type prach_format: str
        :param activate_prach_format_c2: activate prach format c2 or not.
        :type activate_prach_format_c2: bool
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        setattr(self, 'nrarfcn_downlink', nrarfcn_downlink)
        setattr(self, 'nrarfcn_uplink', nrarfcn_uplink)
        setattr(self, 'nrarfcn', nrarfcn)
        setattr(self, 'pfa_target', pfa_target)
        setattr(self, 'prach_config_index', prach_config_index)
        timeout = int(timeout)
        setattr(self, 'root_seq_index', root_seq_index)
        setattr(self, 'zero_zone_config', zero_zone_config)
        setattr(self, 'prach_seq_type', prach_seq_type)
        self._setup_common_params(local_cell=local_cell,
                                    rep_time_int=rep_time_int,
                                    reception_slot=reception_slot,
                                    expectation_slot=expectation_slot,
                                    beam_id=beam_id,
                                    ru_mode=ru_mode,
                                    physical_cell_id=physical_cell_id,
                                    preamble_index=preamble_index,
                                    accepted_timing_error=accepted_timing_error,
                                    constant_offset=constant_offset,
                                    delay_pattern_duration=delay_pattern_duration,
                                    nrarfcn_downlink=nrarfcn_downlink,
                                    nrarfcn_uplink=nrarfcn_uplink,
                                    nrarfcn=nrarfcn,
                                    pfa_target=pfa_target,
                                    prach_config_index=prach_config_index,
                                    root_seq_index=root_seq_index,
                                    zero_zone_config=zero_zone_config,
                                    timeout=timeout,
                                    test_type='PRACH')

        self._insert_optional_parameters(parameters_dict=locals(), timeout=timeout)

        _PRACH_FORMAT_LIST_BUTTON_XPATH = '//div[contains(text(), "PRACH format:")]/parent::*//button'
        _PRACH_FORMAT_LIST_OPTIONS_XPATH = '//div[contains(text(), "PRACH format:")]/parent::*//ul//li'
        if prach_format:
            self.select_element_from_dropdown_list_by_text_and_click(
                prach_format,
                (By.XPATH, _PRACH_FORMAT_LIST_BUTTON_XPATH),
                (By.XPATH, _PRACH_FORMAT_LIST_OPTIONS_XPATH),
                timeout)
        if activate_prach_format_c2:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_PRACH_FORMAT_C2_RADIO_TRUE), timeout)
        else:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_PRACH_FORMAT_C2_RADIO_FALSE), timeout)

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def wait_for_test_to_start(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Start test succeed and test is ongoing.', timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G performance test.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._STOP_TEST_BUTTON_XPATH.format(test_id)), timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for performance test to be successfully stopped.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Stop succeed.', timeout)

    def get_carrier_frequency(self, timeout):
        """
        Gets value of carrier frequency from Performance Test Page.
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: Value of carrier frequency if is available, None otherwise.
        :rtype: float
        """
        carrier_freq = self.get_text_by_xpath(self._CARRIER_FREQUENCY_VALUE_LABEL_XPATH, timeout)
        carrier_freq = carrier_freq.split(' ')[0]
        carrier_freq = carrier_freq.replace(',', '')
        return float(carrier_freq) if carrier_freq else None

    def is_test_available(self, local_cell, frc_index, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: Name of local cell which checked test should contain.
        :type local_cell: str
        :param frc_index: Name of frc index which checked test should contain.
        :type frc_index: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise.
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(
                self._TESTS_TABLE_ROW_BY_CELL_AND_MODEL_XPATH.format(local_cell.split('-')[1], frc_index), timeout)
        except TimeoutException:
            return False
        return True

    def get_test_parameters_table(self, test_id, timeout):
        """
        Gets whole Test parameters table.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists.
        :rtype: {str: [str, ]}
        :raises ValueError: when test ID has incorrect value.
        """
        self._select_test_from_table(test_id, timeout)
        self.wait_for_visibility((By.XPATH, self._TEST_PARAMETERS_TABLE_XPATH), timeout)
        table = HTMLTable(self.driver, self._TEST_PARAMETERS_TABLE_XPATH)
        return table.get_table()

