    def _configure_multiple_input(self, input_value, input_xpath):
        if input_value is not None:
            input_value_list = str(input_value).split(':')
            elems = self.driver.find_elements_by_xpath(input_xpath)
            for _ in range(len(elems) - len(input_value_list)):
                input_value_list.append('')
            for index, elem in enumerate(elems):
                if input_value_list[index]:
                    self.input_text_to_field_by_element(elem, input_value_list[index])

    def _configure_nrarfcn(self, timeout):
        value = getattr(self, 'nrarfcn_downlink')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn_downlink'] + '//input'),
                                               value,
                                               timeout)
        value = getattr(self, 'nrarfcn_uplink')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn_uplink'] + '//input'),
                                               value,
                                               timeout)

        value = getattr(self, 'nrarfcn')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn'] + '//input'),
                                               value,
                                               timeout)

    def _configure_root_seq_index(self):
        root_seq_index = getattr(self, 'root_seq_index')
        if root_seq_index is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._PRACH_ROOT_SEQUENCE_INDEX),
                root_seq_index)

    def _configure_zero_zone_config(self):
        zero_zone_config = getattr(self, 'zero_zone_config')
        if zero_zone_config is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._ZERO_CORRE_ZONE_CONFIG),
                zero_zone_config)

    def _configure_pfa_target(self):
        _PFA_TARGET_LIST_BUTTON_XPATH = '//div[contains(text(), "Probability false alarm")]/parent::*//button'
        _PFA_TARGET_LIST_OPTIONS_XPATH = '//div[contains(text(), "Probability false alarm")]/parent::*//ul//li'
        pfa_target = getattr(self, 'pfa_target', None)
        if pfa_target:
            self.select_element_from_dropdown_list_by_text_and_click(
                pfa_target,
                (By.XPATH, _PFA_TARGET_LIST_BUTTON_XPATH),
                (By.XPATH, _PFA_TARGET_LIST_OPTIONS_XPATH))

    def _configure_prach_config_index(self):
        prach_config_index = getattr(self, 'prach_config_index', None)
        if prach_config_index is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._param_root_xpath.format('PRACH configuration index') + '//input'),
                prach_config_index)

    def _configure_prach_sqe_type(self):
        _SEQ_TYPE_TARGET_LIST_BUTTON_XPATH = '//div[contains(text(), "PRACH sequence type")]/parent::*//button'
        _SEQ_TYPE_TARGET_LIST_OPTIONS_XPATH = '//div[contains(text(), "PRACH sequence type")]/parent::*//ul//li'
        prach_seq_type = getattr(self, 'prach_seq_type', None)
        if prach_seq_type:
            self.select_element_from_dropdown_list_by_text_and_click(
                prach_seq_type,
                (By.XPATH, _SEQ_TYPE_TARGET_LIST_BUTTON_XPATH),
                (By.XPATH, _SEQ_TYPE_TARGET_LIST_OPTIONS_XPATH))

    def _setup_common_params(self, *args, **kwargs):
        self.__setup_common_params(*args, **kwargs)
        self._configure_nrarfcn(kwargs['timeout'])
        if kwargs['test_type'] == 'PRACH':
            self._configure_pfa_target()
            self._configure_prach_config_index()
            self._configure_root_seq_index()
            self._configure_zero_zone_config()
            self._configure_prach_sqe_type()

    def __setup_common_params(self, local_cell, beam_id, ru_mode, rep_time_int,
                              physical_cell_id, timeout, test_type, *args, **kwargs):
        """
        Some params of Performance Test Modules are common for every test type.
        Perform setup common parameters.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param rep_time_int: Reporting time interval (in seconds) between
        following measures.
        :type rep_time_int: int
        :param physical_cell_id: value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :param test_type: Type of test to be set up. User have to provide exact name,
        e.g. "PUSCH"
        :type test_type: str
        """
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout)

        self.select_element_from_dropdown_list_by_text_and_click(
            test_type,
            (By.XPATH, self._TEST_TYPE_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._TEST_TYPE_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout)

        self._configure_multiple_input(beam_id, self._BEAM_PATTERN_ID_INPUT_XPATH)

        if ru_mode is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                ru_mode,
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._RU_MODE_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout)

        self.insert_text_to_enable_element((By.XPATH, self._REPORTING_TIME_INTERVAL_INPUT_XPATH),
                                           str(rep_time_int), timeout)

        if physical_cell_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH), str(physical_cell_id),
                                               timeout)

    @staticmethod
    def _check_test_id(test_id):
        if test_id < 1:
            raise ValueError("Performance test ID can't be lower then 1 but it was {}"
                             "".format(test_id))

    def _select_test_from_table(self, test_id, timeout):
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._TESTS_TABLE_ROW_XPATH.format(test_id)), timeout)

    def _insert_optional_parameters(self, parameters_dict, timeout):
        optional_param_names = ('reception_slot', 'expectation_slot', 'preamble_index', 'accepted_timing_error',
                                'constant_offset', 'delay_pattern_duration')

        optional_params = {key: value for key, value in parameters_dict.items()
                           if key in optional_param_names and value is not None}

        for param, value in optional_params.items():
            _INPUT_XPATH = ('//div[contains(text(), "{0}:")]'
                            '/parent::*//input').format(str(param).replace('_', ' ').capitalize())
            self.insert_text_to_enable_element((By.XPATH, _INPUT_XPATH), str(value),
                                               timeout)
